  where not exists(select 1 from functions p join pg_language l on l.oid=p.prolang where p.oid=to_regprocedure(required.signature) and not p.prosecdef and p.provolatile='i' and l.lanname='plpgsql' and pg_get_userbyid(p.proowner)='postgres'))
 -- SPEC08 Capture document contracts: nominal existence, complete reviewed body,
 -- owner, exact configuration, pure/trigger volatility and no private client ACL.
 --023–025: complete reviewed function metadata. Pure DTO functions must not gain
 --stateful/definer authority; stateful readers keep their exact private gates.
 union all select 'spec_evolution_function',e.signature,exists(select 1 from functions p join pg_language l on l.oid=p.prolang
  where p.oid=to_regprocedure(e.signature) and p.prokind='f' and not p.proretset and p.prorettype=to_regtype(e.result_type)
   and p.provolatile=e.volatility::"char" and p.prosecdef=e.definer and not p.proisstrict and not p.proleakproof and p.proparallel='u' and p.provariadic=0
   and p.proconfig=array['search_path=""'] and l.lanname=e.language_name and pg_get_userbyid(p.proowner)='postgres'
   and p.proargnames is not distinct from e.arg_names and p.proargmodes is null and p.pronargdefaults=e.default_count
   and encode(sha256(convert_to(pg_get_expr(p.proargdefaults,0),'UTF8')),'hex') is not distinct from e.default_digest
   and (select count(*) from aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))))=case when e.service then 2 else 1 end
   and exists(select 1 from aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a where a.grantee=p.proowner and a.grantor=p.proowner and a.privilege_type='EXECUTE' and not a.is_grantable)
   and (not e.service or exists(select 1 from aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a where a.grantee='service_role'::regrole and a.grantor=p.proowner and a.privilege_type='EXECUTE' and not a.is_grantable))
   and not exists(select 1 from aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a where a.grantor<>p.proowner or a.is_grantable or a.privilege_type<>'EXECUTE' or (a.grantee<>p.proowner and (not e.service or a.grantee<>'service_role'::regrole)))
   and (e.body_digest is null or octet_length(convert_to(replace(p.prosrc,E'\r\n',E'\n'),'UTF8'))=e.body_bytes
    and encode(sha256(convert_to(replace(p.prosrc,E'\r\n',E'\n'),'UTF8')),'hex')=e.body_digest)) from expected_spec08_function e
 union all select 'onboarding_function',e.signature,exists(select 1 from functions p join pg_language l on l.oid=p.prolang
  where p.oid=to_regprocedure(e.signature) and p.prokind='f' and not p.proretset and p.prorettype=to_regtype(e.result_type)
   and p.provolatile=e.volatility::"char" and p.prosecdef=e.definer and not p.proisstrict and not p.proleakproof and p.proparallel='u' and p.provariadic=0
   and p.proconfig=array['search_path=""'] and l.lanname=e.language_name and pg_get_userbyid(p.proowner)='postgres'
   and p.proargnames is not distinct from e.arg_names and p.proargmodes is null and p.pronargdefaults=e.default_count
   and encode(sha256(convert_to(pg_get_expr(p.proargdefaults,0),'UTF8')),'hex') is not distinct from e.default_digest
   and (select count(*) from aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))))=case when e.service then 2 else 1 end
   and exists(select 1 from aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a where a.grantee=p.proowner and a.grantor=p.proowner and a.privilege_type='EXECUTE' and not a.is_grantable)
   and (not e.service or exists(select 1 from aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a where a.grantee='service_role'::regrole and a.grantor=p.proowner and a.privilege_type='EXECUTE' and not a.is_grantable))
   and not exists(select 1 from aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a where a.grantor<>p.proowner or a.is_grantable or a.privilege_type<>'EXECUTE' or (a.grantee<>p.proowner and (not e.service or a.grantee<>'service_role'::regrole)))
   and (e.body_digest is null or octet_length(convert_to(replace(p.prosrc,E'\r\n',E'\n'),'UTF8'))=e.body_bytes
    and encode(sha256(convert_to(replace(p.prosrc,E'\r\n',E'\n'),'UTF8')),'hex')=e.body_digest)) from expected_onboarding_function e
 union all select 'onboarding_relation',e.name,exists(select 1 from pg_class c
  where c.oid=to_regclass(e.name) and c.relkind='r' and c.relpersistence='p' and c.relrowsecurity and not c.relforcerowsecurity
   and pg_get_userbyid(c.relowner)='postgres' and c.reloptions is null
   and (select jsonb_agg(jsonb_build_object('name',a.attname,'type',format_type(a.atttypid,a.atttypmod),'notNull',a.attnotnull,'generated',a.attgenerated,'identity',a.attidentity,'default',pg_get_expr(d.adbin,d.adrelid)) order by a.attnum)
     from pg_attribute a left join pg_attrdef d on d.adrelid=a.attrelid and d.adnum=a.attnum where a.attrelid=c.oid and a.attnum>0 and not a.attisdropped)=e.expected_columns
   --PG17 stores relation NOT NULL only in pg_attribute; PG18 also creates
   --contype=n rows. Their names are not a cross-version contract. The exact
   --attnotnull bit remains in expected_columns and has an independent negative.
   and (select coalesce(jsonb_agg(jsonb_build_object('name',k.conname,'definition',pg_get_constraintdef(k.oid),'validated',k.convalidated,'local',k.conislocal,'noInherit',k.connoinherit) order by k.conname),'[]') from pg_constraint k where k.conrelid=c.oid and k.contype<>'n')=e.expected_constraints
   and (select coalesce(jsonb_agg(jsonb_build_object('name',ic.relname,'definition',pg_get_indexdef(i.indexrelid),'valid',i.indisvalid,'ready',i.indisready,'live',i.indislive) order by ic.relname),'[]') from pg_index i join pg_class ic on ic.oid=i.indexrelid where i.indrelid=c.oid)=e.expected_indexes
   and (select coalesce(jsonb_agg(jsonb_build_object('name',t.tgname,'definition',pg_get_triggerdef(t.oid),'enabled',t.tgenabled) order by t.tgname),'[]') from pg_trigger t where t.tgrelid=c.oid and not t.tgisinternal)=e.expected_triggers
   and not exists(select 1 from pg_trigger t where t.tgrelid=c.oid and t.tgenabled<>'O')) from expected_onboarding_relation e
